<script setup>
defineProps({id:String,title:String,collapsed:Boolean,zoom:Boolean,loading:Boolean});defineEmits(['toggle','zoom','move']);
</script>
<template><section :id="id" class="cl-panel" :class="{'panel-zoom':zoom}" tabindex="-1" @keydown.esc="$emit('zoom')"><header class="cl-panel-title"><h2>{{title}}</h2><nav><button type="button" @click="$emit('toggle')">{{collapsed?'Expand':'Collapse'}}</button><button type="button" aria-label="Move panel up" @click="$emit('move',-1)">↑</button><button type="button" aria-label="Move panel down" @click="$emit('move',1)">↓</button><button type="button" @click="$emit('zoom')">{{zoom?'Exit fullscreen':'Expand panel'}}</button></nav></header><div v-show="!collapsed"><p v-if="loading" role="status">Loading…</p><slot/></div></section></template>
<style scoped>.cl-panel{background:white;border:1px solid #d7e4dd;border-radius:14px;padding:18px;min-width:0}.cl-panel-title{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:14px}h2{font-size:19px;margin:0}nav{display:flex;gap:6px;flex-wrap:wrap}button{font:inherit;padding:6px 10px;color:#18543a;background:#eff8f1;border:1px solid #c7ddce;border-radius:6px}.panel-zoom{position:fixed;inset:20px;z-index:200;overflow:auto;box-shadow:0 0 0 30px #001b14b0}</style>
